import { mutationGate,capturedHttp,httpFact } from "./w02-mutation";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { writeFileSync,mkdirSync } from "node:fs";
import { join } from "node:path";
import Database from "better-sqlite3";
import { canonicalDigest } from "../../src/domain/request-digest";
import { boundedLaunch,boundedBrowser,boundedProxy } from "./w01-runtime";
import { invokeCli } from "./w01-legacy-performance";
import { capturePendingSpool,validateEventSpool } from "./w01-spool";
import { pairPage } from "./p03";
import { copySeed,type W02Prepared } from "./w02-preparation";
import { browserRequest,dispatchCurrent,validateCliClock,summarizeCurrent,teardownAll,type VisibilityReceipt } from "./w02-measurement";
import { cliWireCapture,validateCliWire,persistCliWire,type CliWireFact } from "./w02-cli-wire";
import type { TaskSnapshot } from "../../src/contracts/tasks";
export type { VisibilityReceipt } from "./w02-measurement";
export async function currentScenario(p:W02Prepared,scenario:number,root:string,receipt:VisibilityReceipt,save:()=>void,transitions=10,enforceBudget=true){
 const dir=copySeed(p,"scenario",join(root,"visibility-"+scenario)),server=await boundedLaunch({dir,cwd:p.sources.head}),resources=[{name:"service",close:server.stop}];let primary:unknown;
 try{const ownedBrowser=await boundedBrowser();resources.unshift({name:"browser",close:ownedBrowser.close});const contexts=await Promise.all([ownedBrowser.browser.newContext({viewport:{width:1440,height:1100}}),ownedBrowser.browser.newContext({viewport:{width:1440,height:1100}})]),pages=await Promise.all(contexts.map(c=>c.newPage()));for(const page of pages)await pairPage(page,server);
 const gate=mutationGate();let setupCounter=0,currentIndex=-1;const seed=p.seeds.head,taskId=p.diamond[3],prerequisiteId=p.diamond[1];
 const association=()=>currentIndex<0?`visibility:${scenario}:initialization`:`visibility:${scenario}:${currentIndex}`;
 const binding=(setup:boolean)=>({source:p.sources.head,dataDir:dir,setup,parentSampleId:association(),context:[0,1]});
 const browserCommandRaw=(path:string,input:unknown,method="POST",key=randomUUID(),setup=false)=>browserRequest(pages[0],path,input,method,key,receipt.originals,save,binding(setup));
 const browserCommand=(path:string,input:unknown,method="POST",key=randomUUID())=>gate.run(()=>browserCommandRaw(path,input,method,key,true),pacing=>{receipt.originals.push({kind:"mutationPermit",pacing});});
 const current=async(id:string)=>{const fact=httpFact({id:`visibility:${scenario}:setup-read:${setupCounter++}`,parentSampleId:association(),setup:true,warmup:false,label:"head",dataDir:dir,operation:"visibility-read"});receipt.originals.push({kind:"httpSetup",fact});const parsed=await capturedHttp(server.url+"/api/v1/tasks/"+id,undefined,"GET",{Authorization:"Bearer "+server.credentials().reporterToken},fact,save,gate);return parsed.data as {task:TaskSnapshot;evidence:TaskSnapshot["evidence"];readiness:TaskSnapshot["readiness"]};};
 let t=(await current(taskId)).task;await browserCommand(`/tasks/${taskId}/dependencies`,{expectedVersion:t.version,prerequisiteIds:scenario===1?[prerequisiteId]:[]},"PUT");
 t=(await current(taskId)).task;await browserCommand(`/tasks/${taskId}/review-policy`,{expectedVersion:t.version,reviewRequired:scenario!==1,verificationRequired:false},"PATCH");
 const token=join(dir,"cli-token"),outbox=join(root,"visibility-outbox-"+scenario);writeFileSync(token,server.credentials().reporterToken,{mode:0o600});mkdirSync(outbox,{mode:0o700});let activeCli:CliWireFact|undefined;const wire=cliWireCapture(()=>activeCli,outbox,save),proxy=await boundedProxy(server,wire.decide,{httpMs:10000,closeMs:5000,onFailure:wire.onFailure});resources.unshift({name:"proxy",close:proxy.close});const env={PORT:String(proxy.port),AGENTFLOW_REPORTER_TOKEN_FILE:token,AGENTFLOW_OUTBOX_DIR:outbox};let count=0,cliCount=0;const file=(input:unknown)=>{const path=join(dir,`visibility-input-${count++}.json`);writeFileSync(path,JSON.stringify(input),{mode:0o600});return path;};
 const cliRaw=async(args:string[],setup=false,intentionalOutage=false)=>{const fact:CliWireFact={id:association()+":cli:"+cliCount++,parentSampleId:association(),source:p.sources.head,dataDir:dir,setup,context:[0,1],attempts:[],failure:null,persistenceFailure:null,intentionalOutage};const original={kind:"cliWire",fact,args,result:null as Awaited<ReturnType<typeof invokeCli>>|null};receipt.originals.push(original);persistCliWire(fact,save);activeCli=fact;try{const result=await invokeCli(p.sources.head,args,env);original.result=result;for(const attempt of fact.attempts)if(attempt.path.endsWith("/events")&&attempt.status!==null&&attempt.status>=200&&attempt.status<300)receipt.originals.push({kind:"eventACK",input:attempt.input,status:attempt.status,text:attempt.text,generation:attempt.generation,retryAfter:attempt.retryAfter,attempt});persistCliWire(fact,save);if(intentionalOutage){assert.equal(result.code,2,result.stderr);validateCliWire(fact);return result;}validateCliWire(fact);validateCliClock(result);return JSON.parse(result.stdout);}finally{activeCli=undefined;}};
 const cli=(args:string[])=>gate.run(()=>cliRaw(args,true),pacing=>{receipt.originals.push({kind:"mutationPermit",pacing});});
 const register=async(purpose:string,id:string,task:TaskSnapshot)=>{await cli(["run","register","--file",file({id,projectId:seed.projectId,taskId:task.id,agentId:seed.agents[0],purpose,expectedTaskVersion:task.version,...(purpose==="review"?{workRevision:task.workRevision,artifactRef:"synthetic:same",reworkRound:task.reworkRound}:{})}),"--idempotency-key",randomUUID()]);await cli(["report","--run",id,"--type","run.started","--payload",file({})]);};
 const implement=async()=>{const id=randomUUID();await register("implementation",id,(await current(taskId)).task);await cli(["report","--run",id,"--type","run.succeeded","--payload",file({summary:"Synthetic new work",artifactRef:"synthetic:same"})]);};
 if(scenario!==1)await implement();
 if(scenario===1){const prereq=(await current(prerequisiteId)).task;await browserCommand(`/tasks/${prerequisiteId}/dependencies`,{expectedVersion:prereq.version,prerequisiteIds:[]},"PUT");}
 const nodeId=p.workflow.nodeIds[23],url=server.url+`/projects/${seed.projectId}/workflows?workflowId=${p.workflow.workflowId}&revisionId=${p.workflow.revisionId}&nodeId=${nodeId}`;for(let context=0;context<2;context++){await pages[context].goto(url+(context===1?"&view=list":""));await pages[context].locator(`.acceptance-facts[data-task-id="${taskId}"] [data-current-fact="${scenario===1?"readiness":"review"}"]`).evaluate(element=>element.scrollIntoView({block:"center",inline:"nearest",behavior:"instant"}));}
 for(let index=0;index<transitions;index++){currentIndex=index;let origin:string,eventId="",decision="none",ready=true,expectedVersion:number;let dispatch:()=>Promise<unknown>;
  if(scenario===1){let prerequisite=(await current(prerequisiteId)).task;const accepting=index%2===0;if(accepting){await browserCommand(`/tasks/${prerequisiteId}`,{expectedVersion:prerequisite.version,status:"review"},"PATCH");prerequisite=(await current(prerequisiteId)).task;}const key=randomUUID(),path=`/tasks/${prerequisiteId}/${accepting?"complete":"reopen"}`,input=accepting?{expectedVersion:prerequisite.version,evidenceNote:"Synthetic measured prerequisite acceptance"}:{expectedVersion:prerequisite.version,reason:"Synthetic measured prerequisite reopen"};origin="command:"+key;ready=accepting;t=(await current(taskId)).task;expectedVersion=t.version;dispatch=()=>browserCommandRaw(path,input,"POST",key);
  }else if(scenario===3&&index%2===0){t=(await current(taskId)).task;const key=randomUUID();origin="command:"+key;expectedVersion=t.version+1;dispatch=()=>browserCommandRaw(`/tasks/${taskId}/rework`,{expectedVersion:t.version,reason:"Synthetic measured same-reference rework"},"POST",key);t={...t,workRevision:t.workRevision+1,reworkRound:t.reworkRound+1};
  }else{if(scenario===3)await implement();else{t=(await current(taskId)).task;await browserCommand(`/tasks/${taskId}/artifact`,{expectedVersion:t.version,artifactRef:"synthetic:transition-"+index},"POST");
  }t=(await current(taskId)).task;const detail=await current(taskId),ref=detail.evidence.currentArtifact!.artifactRef,id=randomUUID();await cli(["run","register","--file",file({id,projectId:seed.projectId,taskId,agentId:seed.agents[0],purpose:"review",expectedTaskVersion:t.version,workRevision:t.workRevision,artifactRef:ref,reworkRound:t.reworkRound}),"--idempotency-key",randomUUID()]);await cli(["report","--run",id,"--type","run.started","--payload",file({})]);decision=scenario===2&&index%2?"changes_requested":"approved";await gate.run(()=>cliRaw(["report","--run",id,"--type","run.succeeded","--payload",file({summary:"Synthetic measured gate",decision,evidenceNote:"Synthetic transition"})],true,true),pacing=>{receipt.originals.push({kind:"mutationPermit",pacing});});const pending=capturePendingSpool(outbox,{kind:"run",id});assert.equal(pending.length,1);validateEventSpool(pending[0],pending[0].body);eventId=String(pending[0].body!.eventId);origin="event:"+eventId;t=(await current(taskId)).task;expectedVersion=t.version;dispatch=()=>cliRaw(["flush","--run",id]);}
  const artifactRef=scenario===3&&index%2===0?"":(await current(taskId)).evidence.currentArtifact?.artifactRef??"";const expected=pages.map((_,context)=>({projectId:seed.projectId,workflowId:p.workflow.workflowId,revisionId:p.workflow.revisionId,nodeId,scenario,index,context,fact:scenario===1?"readiness" as const:"review" as const,view:context===0?"graph" as const:"list" as const,origin,taskId,version:expectedVersion,workRevision:t.workRevision,reworkRound:t.reworkRound,artifactRef,ready,decision,eventId}));await dispatchCurrent(receipt,expected,pages,dispatch,save,5000,enforceBudget,gate);}
 }catch(error){primary=error;}finally{await teardownAll(primary,resources,receipt.failures);}
 const db=new Database(join(dir,"agentflow.sqlite"),{readonly:true});try{for(const original of receipt.originals){const o=original as {kind:string;path:string;method:string;key:string;input:unknown;text:string;status:number};if(o.kind==="browser"){const row=db.prepare("SELECT * FROM receipts WHERE key=? AND path=? AND method=?").get(o.key,"/api/v1"+o.path,o.method) as {digest:string;body:string;status:number};assert(row);assert.equal(row.digest,canonicalDigest(o.input));assert.equal(row.status,o.status);assert.deepEqual(JSON.parse(row.body),JSON.parse(o.text));}if(o.kind==="eventACK"){const input=o.input as {eventId:string},row=db.prepare("SELECT * FROM run_events WHERE event_id=?").get(input.eventId) as {digest:string;acknowledgement:string};assert(row);assert.equal(row.digest,canonicalDigest(o.input));assert.deepEqual(JSON.parse(row.acknowledgement),JSON.parse(o.text));}}for(const e of receipt.expected.filter(e=>e.context===0&&e.eventId)){const row=db.prepare("SELECT * FROM gate_decisions WHERE event_id=?").get(e.eventId) as {task_id:string;work_revision:number;rework_round:number;artifact_ref:string;decision:string};assert(row);assert.equal(row.task_id,e.taskId);assert.equal(row.work_revision,e.workRevision);assert.equal(row.rework_round,e.reworkRound);assert.equal(row.artifact_ref,e.artifactRef);assert.equal(row.decision,e.decision);}assert.deepEqual(db.pragma("foreign_key_check"),[]);receipt.rows=[...db.prepare("SELECT * FROM gate_decisions").all(),...db.prepare("SELECT * FROM receipts").all(),...db.prepare("SELECT * FROM run_events").all()];save();}finally{db.close();}receipt.summary=summarizeCurrent(receipt.expected,receipt.captures);save();return receipt.summary;
}
